import json, collections
p = "/Users/kevingalligan/devel/framejob/.claude/worktrees/help-docs/docs/site/src/data/features.json"
d = json.load(open(p))
print(type(d), list(d.keys())[:20] if isinstance(d, dict) else len(d))
rows = d if isinstance(d, list) else None
if rows is None:
    for k, v in d.items():
        if isinstance(v, list):
            print(k, len(v), str(v[0])[:300])
            if v and isinstance(v[0], dict) and any(("section" in x) for x in v):
                rows = v
            elif v and isinstance(v[0], dict) and "rows" in v[0]:
                for s in v:
                    print(s.get("id"), s.get("title"), len(s["rows"]))
                    if s.get("id") == "color":
                        rows = s["rows"]
out = [r for r in rows if r.get("section", "color") == "color"]
print(len(out))
print(collections.Counter(r.get("page") for r in out))
for r in out:
    print(json.dumps(r, ensure_ascii=False))

